1	"use client";
2	
3	/**
4	 * Textarea with an @-mention autocomplete that reports mentioned ids.
5	 */
6	import { useRef, useState } from "react";
7	import { cn } from "@/lib/cn";
8	import { resolveMentions } from "@/lib/mentions";
9	import type { UserId } from "@/types/common";
10	import type { MemberWithUser } from "@/types/member";
11	import type { ReactElement } from "react";
12	import {
13	  applyMention,
14	  findMentionQuery,
15	  matchMembers,
16	  mentionHandle,
17	  type MentionQuery,
18	} from "./mention-query";
19	
20	export type MentionTextareaProps = {
21	  value: string;
22	  members: readonly MemberWithUser[];
23	  onChange: (value: string, mentioned: readonly UserId[]) => void;
24	};
25	
26	export function MentionTextarea(
27	  props: MentionTextareaProps,
28	): ReactElement | null {
29	  const { value, members, onChange } = props;
30	  const ref = useRef<HTMLTextAreaElement | null>(null);
31	  const [mention, setMention] = useState<MentionQuery | null>(null);
32	
33	  // `resolveMentions` is the same function the comment service runs on the
34	  // stored body, so what the composer reports and what the server records
35	  // cannot drift apart.
36	  function emit(body: string): void {
37	    onChange(body, resolveMentions(body, members));
38	  }
39	
40	  function handleInput(body: string, caret: number): void {
41	    setMention(findMentionQuery(body, caret));
42	    emit(body);
43	  }
44	
45	  function choose(member: MemberWithUser): void {
46	    if (mention === null) return;
47	    const next = applyMention(value, mention, member);
48	    setMention(null);
49	    emit(next.body);
50	    const element = ref.current;
51	    if (element !== null) {
52	      element.focus();
53	      element.setSelectionRange(next.caret, next.caret);
54	    }
55	  }
56	
57	  const suggestions =
58	    mention === null ? [] : matchMembers(members, mention.query);
59	
60	  return (
61	    <div className="relative">
62	      <textarea
63	        ref={ref}
64	        name="body"
65	        rows={4}
66	        value={value}
67	        className={cn("w-full rounded border p-2 text-sm")}
68	        placeholder="Leave a comment. Use @ to mention a teammate."
69	        onChange={(event) =>
70	          handleInput(event.target.value, event.target.selectionStart)
71	        }
72	        onKeyDown={(event) => {
73	          if (event.key === "Escape" && mention !== null) {
74	            event.preventDefault();
75	            setMention(null);
76	          }
77	        }}
