/**
 * The whole thread for one issue, in reading order: top-level comments oldest
 * first, each followed by every reply that descends from it, however deep the
 * reply chain goes. A deleted comment keeps its place — as a placeholder in
 * the top-level slot, or still anchoring its own replies when it is itself a
 * reply — so nothing beneath it becomes unreachable.
 */
export async function listThread(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly CommentThreadNode[]> {
  const rows = getDb()
    .select({ comment: comments, author: users })
    .from(comments)
    .innerJoin(users, eq(users.id, comments.authorId))
    .where(
      and(
        orgPredicate(comments.orgId, orgId),
        eq(comments.issueId, issueId),
      ),
    )
    .orderBy(asc(comments.createdAt))
    .all();

  const decorated: CommentWithAuthor[] = rows.map((row) => ({
    ...toComment(row.comment),
    author: toUser(row.author),
  }));

  const byId = new Map(decorated.map((comment) => [comment.id, comment]));

  function descendsFrom(comment: CommentWithAuthor, ancestorId: string): boolean {
    let current: CommentWithAuthor | undefined = comment;
    while (current && current.parentId !== null) {
      if (current.parentId === ancestorId) return true;
      current = byId.get(current.parentId);
    }
    return false;
  }

  // `decorated` is already createdAt-ascending, so filtering it preserves
  // posting order across however many branches a thread has grown.
  return decorated
    .filter((comment) => comment.parentId === null)
    .map((comment) => ({
      comment,
      replies: decorated.filter((candidate) => descendsFrom(candidate, comment.id)),
    }));
}

